+import {Options, RuleType} from '../rules';
+import RuleBuilder, {BooleanOptionBuilder, DropdownOptionBuilder, ExampleBuilder, NumberOptionBuilder, OptionBuilderBase, TextAreaOptionBuilder, TextOptionBuilder} from './rule-builder';
+
+type ListStyle = 'bullet' | 'number';
+type OrderedListStyle = 'always-one' | 'increment';
+
+class AutoTocOptions implements Options {
+  listStyle?: ListStyle = 'bullet';
+  bulletMarker?: string = '-';
+  orderedListStyle?: OrderedListStyle = 'always-one';
+  indentSize?: number = 2;
+  minLevel?: number = 2;
+  maxLevel?: number = 6;
+  title?: string = '';
+  useExplicitIds?: boolean = false;
+  stripFormattingInToc?: boolean = false;
+  excludeHeadings?: string[] = [];
+}
+
+type Heading = {level: number, text: string};
+
+const tocStartMarker = /^\\s*<!--\\s*toc\\s*-->\\s*$/i;
+const tocEndMarker = /^\\s*<!--\\s*\\/toc\\s*-->\\s*$/i;
+const atxHeading = /^(?: {0,3})(#{1,6})(?:[ \	]+|$)(.*)$/;
+
+@RuleBuilder.register
+export default class AutoToc extends RuleBuilder<AutoTocOptions> {
+  constructor() {
+    super({
+      nameKey: 'rules.auto-toc.name',
+      descriptionKey: 'rules.auto-toc.description',
+      type: RuleType.CONTENT,
+    });
+  }
+
+  get OptionsClass(): new () => AutoTocOptions {
+    return AutoTocOptions;
+  }
+
+  apply(text: string, options: AutoTocOptions): string {
+    const newline = text.includes('\\r\
') ? '\\r\
' : '\
';
+    const lines = text.split(/\\r?\
/);
+    const startIndex = lines.findIndex((line) => tocStartMarker.test(line));
+    if (startIndex === -1) {
+      return text;
+    }
+
+    const endIndex = lines.findIndex((line, index) => index > startIndex && tocEndMarker.test(line));
+    const headings = this.getHeadings(lines, startIndex, endIndex, options);
+    const tocLines = this.buildToc(lines[startIndex], endIndex === -1 ? '<!-- /toc -->' : lines[endIndex], headings, options);
+
+    // Replace any blank lines following the old end marker as well, so updates are idempotent.
+    let replaceEnd = endIndex === -1 ? startIndex + 1 : endIndex + 1;
+    while (replaceEnd < lines.length && lines[replaceEnd].trim() === '') {
+      replaceEnd++;
+    }
+    lines.splice(startIndex, replaceEnd - startIndex, ...tocLines);
+
+    return lines.join(newline);
+  }
+
+  private getHeadings(lines: string[], tocStart: number, tocEnd: number, options: AutoTocOptions): Heading[] {
+    const headings: Heading[] = [];
+    let inYaml = false;
+    let inCodeFence: string | null = null;
+    let inMathBlock = false;
+
+    for (let index = 0; index < lines.length; index++) {
+      const line = lines[index];
+      const trimmed = line.trim();
+
+      if (index === 0 && trimmed === '---') {
+        inYaml = true;
+        continue;
+      }
+      if (inYaml) {
+        if (trimmed === '---' || trimmed === '...') {
+          inYaml = false;
+        }
+        continue;
+      }
+
+      const fence = line.match(/^ {0,3}(`{3,}|~{3,})/);
+      if (fence) {
+        const marker = fence[1];
+        if (inCodeFence === null) {
+          inCodeFence = marker[0];
+        } else if (inCodeFence === marker[0]) {
+          inCodeFence = null;
+        }
+        continue;
+      }
+      if (inCodeFence !== null) {
+        continue;
+      }
+
+      if (trimmed.startsWith('$$')) {
+        inMathBlock = !inMathBlock;
+        continue;
+      }
+      if (inMathBlock || trimmed === '\\\\[' || trimmed === '\\\\]') {
+        continue;
+      }
+
+      // A missing end marker means the following document content is not yet a TOC region.
+      if (tocEnd !== -1 && index > tocStart && index < tocEnd) {
+        continue;
+      }
+
+      const match = line.match(atxHeading);
+      if (!match) {
+        continue;
+      }
+
+      const level = match[1].length;
+      if (level < options.minLevel || level > options.maxLevel) {
+        continue;
+      }
+
+      const text = cleanHeadingText(match[2]);
+      if (!isExcluded(text, options.excludeHeadings)) {
+        headings.push({level, text});
+      }
+    }
+
+    return headings;
+  }
