+      const indent = ' '.repeat(Math.max(0, heading.level - options.minLevel) * options.indentSize);
+      const anchor = uniqueAnchor(toAnchor(heading.text, options.useExplicitIds), anchors);
+      const label = options.stripFormattingInToc ? stripFormatting(resolveLinks(removeImages(heading.text))) : resolveLinks(removeImages(heading.text));
+      const marker = options.listStyle === 'number' ? `${options.orderedListStyle === 'increment' ? index + 1 : 1}.` : options.bulletMarker;
