+    });
+
+    const result = [startMarker, ''];
+    if (options.title) {
+      result.push(options.title, '');
+    }
+    result.push(...items);
+    if (items.length > 0) {
+      result.push('');
+    }
+    result.push(endMarker, '');
+    return result;
+  }
